bool enqueue(int* arr, int k, int& front, int& rear, int x) {
    if((rear+1)%k==front){cout<<"Overflow"<<endl;return false;}
    if(front==-1) front=0;
    rear=(rear+1)%k;
    arr[rear]=x;
    return true;
}
int dequeue(int* arr, int k, int& front, int& rear) {
    if(front==-1){cout<<"Underflow"<<endl;return -1;}
    int val=arr[front];
    if(front==rear) front=rear=-1;
    else front=(front+1)%k;
    return val;
}

code.python:
class CircularQueue:
    def __init__(self, k):
        self.k = k
        self.q = [0]*k
        self.front = self.rear = -1
    def enqueue(self, x):
        if (self.rear+1)%self.k == self.front:
            print('Overflow'); return
        if self.front == -1: self.front = 0
        self.rear = (self.rear+1)%self.k
        self.q[self.rear] = x
    def dequeue(self):
        if self.front == -1:
            print('Underflow'); return -1
        val = self.q[self.front]
        if self.front == self.rear: self.front = self.rear = -1
        else: self.front = (self.front+1)%self.k
        return val

