code.cpp:
struct Node {
    int key, val;
    Node *prev, *next;
    Node(int k, int v): key(k), val(v), prev(nullptr), next(nullptr){}
};
class LRUCache {
    int cap;
    unordered_map<int, Node*> mp;
    Node *head, *tail;
    void addToHead(Node* n) {
        n->next=head->next; n->prev=head;
        head->next->prev=n; head->next=n;
    }
    void removeNode(Node* n) {
        n->prev->next=n->next; n->next->prev=n->prev;
    }
public:
    LRUCache(int c): cap(c) {
        head=new Node(0,0); tail=new Node(0,0);
        head->next=tail; tail->prev=head;
    }
    int get(int key) {
        if(mp.find(key)==mp.end()) return -1;
        Node* n=mp[key]; removeNode(n); addToHead(n);
        return n->val;
    }
    void put(int key, int val) {
        if(mp.find(key)!=mp.end()){
            Node* n=mp[key]; n->val=val; removeNode(n); addToHead(n);
        } else {
            Node* n=new Node(key,val); mp[key]=n; addToHead(n);
            if((int)mp.size()>cap){
                Node* lru=tail->prev; removeNode(lru);
                mp.erase(lru->key); delete lru;
            }
        }
    }
};

